"""The committed endurance model artifacts (regenerated by
scripts/run_endurance_models.py) must cover the full scope, stay consistent
with a fresh recomputation (no drift between code and the CSVs), and back the
specific numeric claims the hand-written reports make."""

from __future__ import annotations

from pathlib import Path

import pandas as pd
import pytest

from src.data.endurance_loader import EnduranceLoader
from src.data.endurance_scope import scoped_race_seasons
from src.degradation.endurance import build_endurance_frame, fit_endurance_degradation
from src.ingestion.config import ENDURANCE_DERIVED_DIR


@pytest.fixture(scope="module")
def fits() -> pd.DataFrame:
    return pd.read_csv(ENDURANCE_DERIVED_DIR / "endurance_degradation_fits.csv")


@pytest.fixture(scope="module")
def loro() -> pd.DataFrame:
    return pd.read_csv(ENDURANCE_DERIVED_DIR / "endurance_degradation_loro.csv")


def test_artifacts_cover_the_full_scope(fits) -> None:
    assert len(fits) == len(scoped_race_seasons())  # one row per circuit-season
    # Asserted as a superset-of-the-known rather than an exact set: the scope
    # grows as series and classes are added (ELMS joined IMSA and WEC), and an
    # exact match would fail on every widening for no reason. What must hold is
    # that nothing modelled has silently vanished.
    assert {"imsa", "wec"} <= set(fits["series"])


def test_committed_fits_match_a_fresh_recomputation(fits) -> None:
    """Guard against drift: regenerate two circuit-seasons and check the
    committed CSV still matches, so the artifacts can't silently go stale."""
    for series, event, cls, season in (("wec", "Bahrain", "HYPERCAR", 2024),
                                        ("imsa", "Road America", "GTP", 2024)):
        fresh = fit_endurance_degradation(
            build_endurance_frame(EnduranceLoader(series).load_laps(season, event, cls))
        )
        row = fits[(fits["series"] == series) & (fits["event"] == event)
                   & (fits["season"] == season)].iloc[0]
        assert row["net_slope"] == pytest.approx(round(fresh.net_slope.value, 4), abs=1e-4)
        assert row["rmse_s"] == pytest.approx(round(fresh.rmse_s, 3), abs=1e-3)


def test_separability_claim_matches_the_report(fits) -> None:
    """The fuel/degradation split is identified at exactly one circuit, and the
    reason is the race format rather than the car.

    Sebring is separable in **all three IMSA classes at both editions** — GTP
    0.826/0.820, GTD 0.708/0.695, GTD PRO 0.861/0.848 — and nowhere else in
    any series. Its 12 h format carries enough fuel-only splash stops to
    weaken the fuel/tyre collinearity that makes the split unidentified
    everywhere else.

    Six concordant observations, where an earlier version of this test had two
    plus Indianapolis 2024 sitting 0.003 the right side of the 0.90 cutoff and
    flagged as the threshold coincidence it was. That artefact disappeared
    when the field-wide filter gained hysteresis and stopped keeping the
    recovery laps after a neutralisation — which is what a spurious result
    looks like when the noise causing it is removed.
    """
    imsa = fits[fits["series"] == "imsa"]
    separable = fits[fits["separable"]]
    assert set(separable["event"]) == {"Sebring"}, (
        f"separability escaped Sebring: {sorted(set(separable['event']))}"
    )
    # All three IMSA classes, both editions each.
    assert set(separable["car_class"]) == {"GTP", "GTD", "GTDPRO"}
    assert len(separable) == 6
    assert (separable["fuel_deg_corr"] < 0.87).all()
    # Every other race in every series stays collinear.
    assert not fits[fits["event"] != "Sebring"]["separable"].any()
    assert len(imsa) > 100


def test_loro_backs_the_bahrain_exception(loro) -> None:
    """The WEC report's headline exception: Bahrain's slope genuinely transfers
    across seasons (mean LORO R2 well positive), unlike Watkins Glen."""
    bahrain = loro[(loro["event"] == "Bahrain") & (loro["held_out_season"] == "MEAN")]
    glen = loro[(loro["event"] == "Watkins Glen") & (loro["held_out_season"] == "MEAN")]
    assert float(bahrain["r2_within"].iloc[0]) > 0.15
    assert float(glen["r2_within"].iloc[0]) < 0.05


def test_endurance_overtaking_difficulty_is_measured_and_stable() -> None:
    """Track-position value reaches WEC/IMSA too (position reconstructed from
    cumulative time). Values must be physical and the committed artifact must
    match a fresh recomputation for a sample circuit."""
    from src.data.endurance_loader import EnduranceLoader
    from src.data.endurance_scope import ENDURANCE_SCOPE
    from src.simulator.track_position import (
        adjacent_swap_rate_endurance,
        measure_circuit,
    )

    art = pd.read_csv(ENDURANCE_DERIVED_DIR / "endurance_overtaking_difficulty.csv")
    assert {"imsa", "wec"} <= set(art["series"])
    assert art["adj_swap_rate"].between(0.0, 0.15).all()  # physical
    assert (art["p_hold_15_laps"].between(0.0, 1.0)).all()

    # Drift guard: recompute one circuit (whichever sits at this scope index —
    # any circuit works, the assertion below is dynamic) and match the
    # committed value.
    cs = ENDURANCE_SCOPE["wec"][2]
    races = {str(y): EnduranceLoader("wec").load_laps(y, cs.event, cs.car_class)
             for y in cs.seasons}
    fresh = measure_circuit(races, cs.event, rate_fn=adjacent_swap_rate_endurance)
    row = art[(art["series"] == "wec") & (art["circuit"] == cs.event)].iloc[0]
    assert row["adj_swap_rate"] == pytest.approx(round(fresh.swap_rate, 4), abs=1e-4)


def test_pit_procedure_confirms_the_wec_sequential_rule() -> None:
    """WEC changes tyres only after the fuel hose is out (sequential), IMSA does
    both at once (parallel), so WEC's tyre-change premium must be far larger.
    Both a data-backed claim and a drift guard on the committed artifact.

    Compared **like class against like class** — WEC HYPERCAR against IMSA
    GTP, both top prototypes. The premium is a rulebook effect in kind but a
    car property in magnitude, so pooling IMSA's GTD in with its GTP would
    average a GT3 tyre service into a prototype's and answer a question nobody
    asked. That pooling was invisible while each series had one class in scope.
    """
    proc = pd.read_csv(ENDURANCE_DERIVED_DIR / "endurance_pit_procedure.csv")
    assert "car_class" in proc.columns, "the premium must be reported per class"
    prem = proc.set_index(["series", "car_class"])["tyre_change_premium_s"]
    imsa_prem = float(prem[("imsa", "GTP")])
    wec_prem = float(prem[("wec", "HYPERCAR")])
    assert 0 < imsa_prem < 15          # tyres largely hidden behind the fuel fill
    assert wec_prem > 18               # full tyre service added on top
    # Bound loosened on the widened scope (2.5x -> 2.0x): the pooled ratio is
    # ~2.5x on 33 IMSA + 28 WEC prototype races, still a clear procedural gap.
    assert wec_prem > 2.0 * imsa_prem  # the procedural difference, quantified

    # GTD is measured in its own right rather than folded into GTP.
    assert ("imsa", "GTD") in prem.index
    assert float(prem[("imsa", "GTD")]) > 0


# --- class identity, now carried rather than assumed away --------------------


def test_artifacts_identify_the_car_class() -> None:
    """A race-season is not identified by (series, event, season) alone.

    A series can field more than one class at the same event — IMSA runs GTP
    and GTD at every round — so without a class column two classes' rows are
    indistinguishable on every key a consumer would naturally merge or filter
    on. ``run_multistop.py`` additionally keyed its results by
    (series, event) and would have kept only whichever class came last.

    Pinned because the failure is silent in both directions: nothing errors,
    a row simply describes a different car than the reader thinks. This is
    the prerequisite for scoping IMSA GTD alongside GTP
    (``reports/new_series_survey_phase0.md``).
    """
    for name in ("endurance_degradation_fits.csv", "multistop_plans.csv",
                 "endurance_data_quality.csv", "endurance_degradation_loro.csv",
                 "endurance_overtaking_difficulty.csv"):
        art = pd.read_csv(ENDURANCE_DERIVED_DIR / name)
        assert "car_class" in art.columns, f"{name} does not identify the car class"
        assert art["car_class"].notna().all(), f"{name} has rows with no class"


def test_every_artifact_row_is_uniquely_keyed_with_the_class() -> None:
    """With the class in the key, one row per (series, event, class, season).

    The point of the previous test is only realised if the extended key is
    actually unique — a class column that still leaves duplicates would look
    like a fix while changing nothing.
    """
    fits = pd.read_csv(ENDURANCE_DERIVED_DIR / "endurance_degradation_fits.csv")
    key = ["series", "event", "car_class", "season"]
    assert not fits.duplicated(key).any(), fits[fits.duplicated(key, keep=False)][key]

    plans = pd.read_csv(ENDURANCE_DERIVED_DIR / "multistop_plans.csv")
    plan_key = ["series", "circuit", "car_class"]
    assert not plans.duplicated(plan_key).any()


def test_scope_has_no_literally_duplicated_entry() -> None:
    """The real invariant, arrived at after getting it wrong twice.

    The first version forbade any two event strings mapping to one circuit.
    That blocks a *rename*: covering Canadian Tire Motorsport Park (2026)
    means scoping it beside Mosport, because the source renamed the track.

    The second version allowed renames but forbade two names for one circuit
    in the same season, on the theory that this meant a duplicated race. It
    does not: IMSA ran two races at Watkins Glen in 2021, and the source names
    them separately — ``Watkins Glen 240`` is 57 laps and 12 cars, ``Watkins
    Glen 6 Hours`` is 179 laps and 14. Two distinct races at one track in one
    year, both legitimate.

    Both versions encoded a *supposed consequence* instead of the invariant.
    The invariant was never "one name per circuit-season"; it is that
    validation folds group on the **canonical circuit**, which
    ``circuit_canonical`` in every artifact now carries and
    ``test_artifacts_carry_a_canonical_circuit_identity`` checks. What is left
    to assert here is only that no entry is literally repeated — the same
    series, event and class scoped twice, which would load the same laps twice
    for no reason.
    """
    from src.data.endurance_scope import ENDURANCE_SCOPE

    seen: set[tuple[str, str, str]] = set()
    for series, circuits in ENDURANCE_SCOPE.items():
        for cs in circuits:
            key = (series, cs.event, cs.car_class)
            assert key not in seen, f"{key} is scoped more than once"
            seen.add(key)


def test_artifacts_carry_a_canonical_circuit_identity() -> None:
    """Validation folds must group on the circuit, not on the source's string.

    ``circuit``/``event`` stays the name the upstream data uses, so a row can
    still be traced to the file it came from; ``circuit_canonical`` is the
    identity a leave-one-circuit-out fold has to group on. They differ only
    where a track was renamed upstream — today nowhere, which is why this can
    be added without moving a single number, and exactly why it should be
    added now rather than in the same change that first scopes an alias.
    """
    from src.data.endurance_scope import canonical_circuit

    for name, src in (("endurance_degradation_fits.csv", "event"),
                      ("endurance_data_quality.csv", "event"),
                      ("endurance_degradation_loro.csv", "event"),
                      ("endurance_overtaking_difficulty.csv", "circuit"),
                      ("multistop_plans.csv", "circuit")):
        art = pd.read_csv(ENDURANCE_DERIVED_DIR / name)
        assert "circuit_canonical" in art.columns, f"{name} has no canonical circuit"
        assert art["circuit_canonical"].notna().all()

    # And it must actually be the canonical map's output, not a copy of the
    # source column that would silently stop tracking it.
    fits = pd.read_csv(ENDURANCE_DERIVED_DIR / "endurance_degradation_fits.csv")
    expected = fits["event"].map(canonical_circuit)
    assert (fits["circuit_canonical"] == expected).all()


def test_a_near_spec_field_does_not_rescue_slope_transfer(loro) -> None:
    """The control experiment ELMS was scoped to run, and its negative result.

    Phase 0 predicted this would be decisive either way. The season-to-season
    instability of degradation slopes, measured everywhere in this project
    since its F1 phase, had an obvious candidate cause: heterogeneous
    manufacturer prototypes equalised by a Balance of Performance that moves
    between races. ELMS's LMP2 is close to a one-make formula — same Oreca 07
    chassis, same Gibson engine for everyone — so if slopes transferred there,
    the machinery was the explanation.

    They do not. Every ELMS circuit's leave-one-race-out mean within-stint R²
    sits at or below zero, at Portimao markedly below it. A pooled slope
    explains none of a held-out season's variance on a field where the car is
    the same for everyone, so whatever drives the instability is not the car.

    Pinned as a finding, not as a threshold to defend: if a future season made
    ELMS slopes transfer, that would be a real discovery and this test should
    fail loudly rather than be quietly relaxed.
    """
    elms = loro[(loro["series"] == "elms") & (loro["held_out_season"] == "MEAN")]
    assert len(elms) >= 8, "expected both ELMS classes across several circuits"
    r2 = elms["r2_within"].astype(float)
    assert r2.max() < 0.10, (
        f"an ELMS circuit now transfers (max R² {r2.max():.3f}) — the near-spec "
        "control no longer supports 'the instability is not the hardware'"
    )
    assert r2.median() <= 0.0


# --- the gap that let ELMS be scoped without a traffic layer -----------------


def test_every_artifact_covers_every_scoped_series() -> None:
    """A series in the scope must appear in every artifact that has a series
    column, or be listed here as a stated exception.

    This is the check that was missing. ELMS was scoped, materialised, fitted
    and written up while `endurance_traffic_cost.csv` and
    `endurance_traffic_stability.csv` still held only IMSA and WEC — nothing
    failed, because no test asserted that an artifact covers the scope it is
    generated from. The defect was found by reading a CSV by hand.

    The shape of that mistake is the general one: adding a series without
    checking what it makes incomplete elsewhere. A coverage assertion catches
    it for every future addition, which reading by hand does not.
    """
    from src.data.endurance_scope import ENDURANCE_SCOPE

    scoped = set(ENDURANCE_SCOPE)
    artifacts = [
        "endurance_degradation_fits.csv",
        "endurance_degradation_loro.csv",
        "endurance_data_quality.csv",
        "endurance_overtaking_difficulty.csv",
        "endurance_pit_procedure.csv",
        "multistop_plans.csv",
        "fuel_limited_audit.csv",
        "endurance_traffic_cost.csv",
        "endurance_traffic_stability.csv",
    ]
    missing: dict[str, set[str]] = {}
    for name in artifacts:
        art = pd.read_csv(ENDURANCE_DERIVED_DIR / name)
        if "series" not in art.columns:
            continue
        gap = scoped - set(art["series"])
        if gap:
            missing[name] = gap

    assert not missing, (
        f"scoped series absent from artifacts: {missing}. Either regenerate "
        "them, or — if the omission is deliberate — say so here rather than "
        "leaving the artifact quietly narrower than the scope."
    )


def test_the_discovery_catalogue_can_see_every_scoped_class() -> None:
    """The availability scan must at least look at what the project models.

    ``discover_endurance_events.py`` used a hand-written map of one prototype
    class per series, so the catalogue it produced was structurally unable to
    contain GTD, GTD PRO, ELMS or LMP2 Pro/Am — and anything reading that
    catalogue inherited the blindness. The demo did, and offered 2 of 6 scoped
    classes for weeks without a single test failing.

    The scan is now seeded from ``ENDURANCE_SCOPE`` plus explicit unscoped
    candidates. This asserts the seeding, not the network result, so it runs
    offline: a scoped class must always be a scan target.
    """
    import importlib.util

    from src.data.endurance_scope import ENDURANCE_SCOPE

    spec = importlib.util.spec_from_file_location(
        "_discover", Path(__file__).resolve().parents[1]
        / "scripts" / "discover_endurance_events.py"
    )
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)

    targets = set(module._scan_targets())
    scoped = {
        (series, cs.car_class)
        for series, circuits in ENDURANCE_SCOPE.items()
        for cs in circuits
    }
    assert scoped <= targets, (
        f"scoped classes the availability scan cannot see: {sorted(scoped - targets)}"
    )
    # ... and it still looks beyond the scope, which is its actual job.
    assert targets - scoped, "the scan covers only what is already scoped"
